313:   ctx.fillRect(shop.x - 18, shop.y - 26, 10, 20);
314:   ctx.fillRect(shop.x + 8, shop.y - 26, 10, 20);
315: 
316:   for (const suspect of worldState.suspects) {
317:     if (suspect.captured) continue;
318:     ctx.fillStyle = '#ff646e';
319:     ctx.beginPath();
320:     ctx.arc(suspect.x, suspect.y, suspect.radius, 0, Math.PI * 2);
321:     ctx.fill();
322:     ctx.fillStyle = '#ffd7dd';
323:     ctx.fillRect(suspect.x - 12, suspect.y - 26, 24, 10);
324:   }
325: 
326:   for (const item of worldState.evidence) {
327:     if (item.collected) continue;
328:     ctx.fillStyle = '#f7d85c';
329:     ctx.beginPath();
330:     ctx.arc(item.x, item.y, item.radius, 0, Math.PI * 2);
331:     ctx.fill();
332:     ctx.fillStyle = '#533f00';
333:     ctx.fillRect(item.x - 2, item.y - 20, 4, 40);
334:     ctx.fillRect(item.x - 16, item.y - 2, 32, 4);
335:   }
336: 
337:   ctx.restore();
338: }
339: 
340: function drawPlayer() {
341:   const x = player.x - camera.x;
342:   const y = player.y - camera.y;
343: 
344:   ctx.save();
345:   ctx.translate(x, y);
346: 
347:   ctx.fillStyle = 'rgba(0,0,0,0.18)';
348:   ctx.beginPath();
349:   ctx.ellipse(0, 26, 18, 8, 0, 0, Math.PI * 2);
350:   ctx.fill();
351: 
352:   ctx.fillStyle = '#f6d3d6';
353:   ctx.beginPath();
354:   ctx.arc(0, -30, 18, 0, Math.PI * 2);
355:   ctx.fill();
356: 
357:   ctx.fillStyle = '#0a0b12';
358:   ctx.beginPath();
359:   ctx.arc(-5, -34, 3.5, 0, Math.PI * 2);
360:   ctx.arc(5, -34, 3.5, 0, Math.PI * 2);
361:   ctx.fill();
362: 
363:   ctx.strokeStyle = '#3b261d';
364:   ctx.lineWidth = 3;
365:   ctx.beginPath();
366:   ctx.moveTo(-8, -16);
367:   ctx.lineTo(-4, 6);
368:   ctx.moveTo(8, -16);
369:   ctx.lineTo(4, 6);
370:   ctx.stroke();
371: 
372:   ctx.fillStyle = '#1c1d20';
373:   ctx.fillRect(-16, -8, 32, 30);
374: 
375:   ctx.strokeStyle = '#d6b9ff';
376:   ctx.lineWidth = 5;
377:   ctx.beginPath();
378:   ctx.moveTo(-10, 22);
379:   ctx.lineTo(-2, 38);
380:   ctx.moveTo(10, 22);
381:   ctx.lineTo(2, 38);
382:   ctx.stroke();
383: 
384:   ctx.fillStyle = '#0d0b12';
385:   ctx.fillRect(-15, 24, 6, 20);
386:   ctx.fillRect(9, 24, 6, 20);
387: 
388:   ctx.restore();
389: }
390: 
391: function drawWorldMarkers() {
392:   ctx.save();
393:   ctx.translate(-camera.x, -camera.y);
394: 
395:   const target = worldState.suspects.find((s) => !s.captured) || worldState.evidence.find((e) => !e.collected);
396:   const markerTarget = target || { x: shop.x, y: shop.y };
397: 
398:   ctx.strokeStyle = 'rgba(147, 226, 255, 0.8)';
399:   ctx.lineWidth = 2;
400:   ctx.beginPath();
401:   ctx.arc(markerTarget.x, markerTarget.y, markerRadius, 0, Math.PI * 2);
402:   ctx.stroke();
403: 
404:   ctx.fillStyle = 'rgba(147, 226, 255, 0.18)';
405:   ctx.beginPath();
406:   ctx.arc(markerTarget.x, markerTarget.y, markerRadius - 8, 0, Math.PI * 2);
407:   ctx.fill();
408: 
409:   ctx.restore();
410: }
411: 
412: function drawHudEffects() {
413:   const viewX = player.x - camera.x;
414:   const viewY = player.y - camera.y;
415: 
416:   if (player.invulnerable > 0) {
417:     ctx.strokeStyle = 'rgba(255, 123, 149, 0.7)';
418:     ctx.beginPath();
419:     ctx.arc(viewX, viewY, player.radius + 10, 0, Math.PI * 2);
420:     ctx.stroke();
421:   }
422: 
423:   const shopDist = distance(player.x, player.y, shop.x, shop.y);
424:   if (shopDist < shop.radius + 40) {
425:     ctx.fillStyle = 'rgba(96, 255, 217, 0.16)';
426:     ctx.beginPath();
427:     ctx.arc(shop.x - camera.x, shop.y - camera.y, 92, 0, Math.PI * 2);
428:     ctx.fill();
429:     ctx.fillStyle = '#99ffeb';
430:     ctx.font = '18px sans-serif';
431:     ctx.fillText('Onarmak için E tuşuna bas', shop.x - camera.x - 85, shop.y - camera.y - 95);
432:   }
433: }
434: 
435: function updateUi() {
436:   const heelPct = Math.max(0, player.heelIntegrity);
437:   const energyPct = Math.max(0, player.energy);
438: 
439:   heelValue.textContent = `${Math.round(heelPct)}%`;
440:   energyValue.textContent = `${Math.round(energyPct)}%`;
441:   heelBar.style.width = `${heelPct}%`;
442:   energyBar.style.width = `${energyPct}%`;
443:   moneyText.textContent = '∞';
444: 
445:   if (player.heelIntegrity <= 30) {
446:     heelBar.style.background = 'linear-gradient(90deg, #ff9f6e, #ff5d73)';
447:   } else {
448:     heelBar.style.background = 'linear-gradient(90deg, #ff8bd7, #d67cff, #a777ff)';
449:   }
450: }
451: 
452: function update(dt) {
453:   if (game.messageTimer > 0) {
454:     game.messageTimer -= dt;
455:     if (game.messageTimer <= 0) {
456:       messageBox.classList.add('hidden');
457:     }
458:   }
459: 
460:   if (game.active) {
461:     updatePlayer(dt);
462:   }
463: 
464:   updateCamera();
465:   updateUi();
466: }
467: 
468: function render() {
469:   drawBackground();
470:   drawWorldMarkers();
471:   drawPlayer();
472:   drawHudEffects();
473: }
474: 
475: let lastFrame = 0;
476: function tick(timestamp) {
477:   const dt = Math.min((timestamp - lastFrame) / 1000 || 0.016, 0.033);
478:   lastFrame = timestamp;
479:   game.time += dt;
480:   update(dt);
481:   render();
482:   requestAnimationFrame(tick);
483: }
484: 
485: resetGame();
486: requestAnimationFrame(tick);

